package com.cju.likelion.cardcollection.collection.controller;
import com.cju.likelion.cardcollection.collection.dto.*; import com.cju.likelion.cardcollection.collection.service.UserCollectionService; import com.cju.likelion.cardcollection.common.api.ApiResponse;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/collections") public class UserCollectionController { private final UserCollectionService service; public UserCollectionController(UserCollectionService service){this.service=service;} @PostMapping public ResponseEntity<ApiResponse<UserCollectionResponse>> create(Authentication a,@Valid @RequestBody CollectionCreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(new ApiResponse<>(service.create(userId(a),r)));} @GetMapping public ResponseEntity<ApiResponse<List<UserCollectionResponse>>> list(Authentication a){return ResponseEntity.ok(new ApiResponse<>(service.list(userId(a))));} @GetMapping("/{id}") public ResponseEntity<ApiResponse<UserCollectionResponse>> get(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(new ApiResponse<>(service.get(userId(a),id)));} @PatchMapping("/{id}") public ResponseEntity<ApiResponse<UserCollectionResponse>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody CollectionUpdateRequest r){return ResponseEntity.ok(new ApiResponse<>(service.update(userId(a),id,r)));} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(Authentication a,@PathVariable UUID id){service.delete(userId(a),id);return ResponseEntity.noContent().build();} @PostMapping("/{id}/cards") public ResponseEntity<ApiResponse<UserCollectionResponse>> addCard(Authentication a,@PathVariable UUID id,@Valid @RequestBody CollectionCardAddRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(new ApiResponse<>(service.addCard(userId(a),id,r)));} @DeleteMapping("/{id}/cards/{cardId}") public ResponseEntity<Void> removeCard(Authentication a,@PathVariable UUID id,@PathVariable UUID cardId){service.removeCard(userId(a),id,cardId);return ResponseEntity.noContent().build();} private UUID userId(Authentication a){return UUID.fromString(a.getName());} }
